// Golden-blob tests: pin the MapletCodec binary layout that mabench writes.
// Both blobs are generated by mabench.format.encode_blob:
//   GOLDEN_1BAND: 1 band, 2x3: [[1.5, NaN, 0.0], [-0.0, 5e-324, 1e308]]
//   GOLDEN_2BAND: 2 bands, 2x3, band-major:
//                 band 0 [[1, 2, 3], [4, 5, 6]], band 1 [[-1, NaN, 0], [10, 20, 30]]
// If MapletCodec's layout changes, these tests fail, and mabench/src/mabench/format.py
// must change with it (a Python test keeps these arrays in sync with the encoder).
#include <MapletCodec.hpp>

#include <array>
#include <cmath>
#include <cstring>
#include <limits>
#include <vector>

#include <gtest/gtest.h>

namespace
{
constexpr std::array<uint8_t, 72> GOLDEN_1BAND = {
    0x02, 0x01, 0x01, 0x00, 0x02, 0x00, 0x00, 0x00, 0x03, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf8, 0x7f,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf8, 0x3f, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0xf8, 0x7f, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0x01, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0xa0, 0xc8, 0xeb, 0x85, 0xf3, 0xcc, 0xe1, 0x7f,
};

constexpr std::array<uint8_t, 120> GOLDEN_2BAND = {
    0x02, 0x01, 0x02, 0x00, 0x02, 0x00, 0x00, 0x00, 0x03, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf8, 0x7f,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf0, 0x3f, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x40,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x40, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x14, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x18, 0x40,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf0, 0xbf, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0xf8, 0x7f, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x24, 0x40, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x34, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x3e, 0x40,
};

constexpr double NaN = std::numeric_limits<double>::quiet_NaN();

Raster::TileSpec benchmarkSpec(uint8_t bands)
{
    Raster::TileSpec spec;
    spec.format = Raster::WireFormat::Binary;
    spec.cellType = Raster::CellType::Float64;
    spec.width = 3;
    spec.height = 2;
    spec.noData = NaN;  // benchmark stores: NaN is the only NoData
    spec.bands = bands;
    return spec;
}

template <std::size_t N>
Raster::CodecStatus decodeGolden(const std::array<uint8_t, N>& blob, const Raster::TileSpec& spec, std::vector<double>& scratch,
                                 Raster::GridView& view)
{
    scratch.assign(spec.cellCount(), 0.0);
    return Raster::decode(reinterpret_cast<const int8_t*>(blob.data()), blob.size(), spec, scratch.data(), scratch.size(), view);
}
}

TEST(MapletCodecGoldenTest, DecodesSingleBandBlob)
{
    std::vector<double> scratch;
    Raster::GridView view;
    ASSERT_EQ(decodeGolden(GOLDEN_1BAND, benchmarkSpec(1), scratch, view), Raster::CodecStatus::Ok);
    ASSERT_EQ(view.bands, 1);
    EXPECT_EQ(view.at(0, 0), 1.5);
    EXPECT_TRUE(view.isNoData(view.at(0, 1)));
    EXPECT_EQ(view.at(0, 2), 0.0);
    EXPECT_FALSE(view.isNoData(view.at(0, 2)));  // zero is data, not NoData
    EXPECT_TRUE(std::signbit(view.at(1, 0)));    // -0.0 survives
    EXPECT_EQ(view.at(1, 1), 5e-324);
    EXPECT_EQ(view.at(1, 2), 1e308);
}

TEST(MapletCodecGoldenTest, DecodesMultiBandBlobBandMajor)
{
    std::vector<double> scratch;
    Raster::GridView view;
    ASSERT_EQ(decodeGolden(GOLDEN_2BAND, benchmarkSpec(2), scratch, view), Raster::CodecStatus::Ok);
    ASSERT_EQ(view.bands, 2);
    EXPECT_EQ(view.cellCount(), 12U);
    EXPECT_EQ(view.at(0, 1, 2), 6.0);
    EXPECT_EQ(view.at(1, 0, 0), -1.0);
    EXPECT_TRUE(view.isNoData(view.at(1, 0, 1)));
    const auto band1 = view.band(1);           // single-band view for per-band kernels
    EXPECT_EQ(band1.bands, 1);
    EXPECT_EQ(band1.at(1, 2), 30.0);
    EXPECT_EQ(band1.at(0, 2), 0.0);
}

TEST(MapletCodecGoldenTest, EncodesByteIdenticalBlobs)
{
    {
        const auto spec = benchmarkSpec(1);
        const double cells[] = {1.5, NaN, 0.0, -0.0, 5e-324, 1e308};
        const Raster::GridView view{cells, 2, 3, spec.noData, 1};
        std::vector<int8_t> out(Raster::encodedSizeBinary(spec));
        uint64_t written = 0;
        ASSERT_EQ(Raster::encode(view, spec, out.data(), out.size(), written), Raster::CodecStatus::Ok);
        ASSERT_EQ(written, GOLDEN_1BAND.size());
        EXPECT_EQ(std::memcmp(out.data(), GOLDEN_1BAND.data(), GOLDEN_1BAND.size()), 0);
    }
    {
        const auto spec = benchmarkSpec(2);
        const double cells[] = {1, 2, 3, 4, 5, 6, -1, NaN, 0, 10, 20, 30};
        const Raster::GridView view{cells, 2, 3, spec.noData, 2};
        std::vector<int8_t> out(Raster::encodedSizeBinary(spec));
        uint64_t written = 0;
        ASSERT_EQ(Raster::encode(view, spec, out.data(), out.size(), written), Raster::CodecStatus::Ok);
        ASSERT_EQ(written, GOLDEN_2BAND.size());
        EXPECT_EQ(std::memcmp(out.data(), GOLDEN_2BAND.data(), GOLDEN_2BAND.size()), 0);
    }
}

TEST(MapletCodecGoldenTest, RejectsMismatchedSpec)
{
    std::vector<double> scratch;
    Raster::GridView view;
    auto zeroNoData = benchmarkSpec(1);
    zeroNoData.noData = 0.0;  // the TileSpec default: would also turn every real 0.0 into NoData
    EXPECT_EQ(decodeGolden(GOLDEN_1BAND, zeroNoData, scratch, view), Raster::CodecStatus::SizeMismatch);
    EXPECT_EQ(decodeGolden(GOLDEN_2BAND, benchmarkSpec(1), scratch, view), Raster::CodecStatus::SizeMismatch);
    EXPECT_EQ(decodeGolden(GOLDEN_1BAND, benchmarkSpec(2), scratch, view), Raster::CodecStatus::SizeMismatch);
    EXPECT_EQ(decodeGolden(GOLDEN_1BAND, benchmarkSpec(0), scratch, view), Raster::CodecStatus::BadDimensions);
}

TEST(MapletCodecGoldenTest, TextPathCarriesAllBands)
{
    const auto binary = benchmarkSpec(2);
    auto text = binary;
    text.format = Raster::WireFormat::Text;
    const double cells[] = {1, 2, 3, 4, 5, 6, -1, NaN, 0, 10, 20, 30};
    const Raster::GridView view{cells, 2, 3, text.noData, 2};
    std::vector<int8_t> out(Raster::encodedSizeTextUpperBound(text));
    uint64_t written = 0;
    ASSERT_EQ(Raster::encode(view, text, out.data(), out.size(), written), Raster::CodecStatus::Ok);
    std::vector<double> scratch(text.cellCount());
    Raster::GridView back;
    ASSERT_EQ(Raster::decode(out.data(), written, text, scratch.data(), scratch.size(), back), Raster::CodecStatus::Ok);
    EXPECT_EQ(back.bands, 2);
    EXPECT_EQ(back.at(1, 1, 2), 30.0);
    EXPECT_TRUE(std::isnan(back.at(1, 0, 1)));
}
